import{_ as a,C as n,o,c as s,E as r,a2 as d}from"./chunks/framework.Cm6XCzck.js";const k=JSON.parse('{"title":"取消了 Agent，子进程真的停了吗？从 Anywhere Agents 看 Agent 运行时的停止证据边界","description":"","frontmatter":{"title":"取消了 Agent，子进程真的停了吗？从 Anywhere Agents 看 Agent 运行时的停止证据边界","date":"2026-08-27","column":"digital-employee","category":"daily","article_type":"engineering-analysis","edition":"research-center","research_question":"一次取消请求、终止命令成功、已知 PID 消失、执行树收拢与重新派工资格，能否被同一个“已停止”状态代替？","summary":"从 Anywhere Agents 对遗留结果与孤儿进程的连续审计出发，结合一份可公开重跑的 Windows 二层进程探针，讨论 Agent 运行时为什么必须把“发出取消”与“证明执行树已经停止”分开。","sources":"/zh/research/evidence/2026-08-27-runtime-semantics-evidence-pack","project_relevance":"first-party-research","item_id":"RSEM-20260827-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-agent-stop-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-27-agent-stop-evidence.md","filePath":"zh/digital-employee/2026-08-27-agent-stop-evidence.md","lastUpdated":1787845954000}'),i={name:"zh/digital-employee/2026-08-27-agent-stop-evidence.md"};function l(c,e,p,h,g,u){const t=n("ArticleCover");return o(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-27-agent-stop-evidence-cover.png",kicker:"数字员工 · 工程研究",title:"取消了 Agent，子进程真的停了吗？从 Anywhere Agents 看 Agent 运行时的停止证据边界",summary:"取消是一项控制动作，停止是一组需要证明的后置条件。PID 消失、命令返回 0、执行树收拢与重新派工资格不能互相代替。",version:"RSEM-20260827-01",status:"工程研究 · 2026-08-27",languageHref:"/en/digital-employee/2026-08-27-agent-stop-evidence",languageLabel:"English"}),e[0]||(e[0]=d(`<h1 id="取消了-agent-子进程真的停了吗-从-anywhere-agents-看-agent-运行时的停止证据边界" tabindex="-1">取消了 Agent，子进程真的停了吗？从 Anywhere Agents 看 Agent 运行时的停止证据边界 <a class="header-anchor" href="#取消了-agent-子进程真的停了吗-从-anywhere-agents-看-agent-运行时的停止证据边界" aria-label="Permalink to &quot;取消了 Agent，子进程真的停了吗？从 Anywhere Agents 看 Agent 运行时的停止证据边界&quot;">​</a></h1><p><strong>取消是一项动作；停止是一组后置条件。</strong></p><p>这两个概念在 Agent 系统里很容易被一枚“已取消”图标合并。用户点击取消，运行时发出终止命令，命令返回成功，于是页面显示“已停止”。但如果旧子进程仍在写文件、某个孙进程已经脱离原进程组，或者结果文件只是暂时不可读，那么“停止成功”其实把几种完全不同的事实压成了一个结论。</p><p>真正重要的问题不是取消按钮有没有生效，而是：<strong>系统到底证明到了哪一层？</strong></p><h2 id="_1-anywhere-agents-先给出了一条很严格的观察规则-看不到-不等于不存在" tabindex="-1">1. Anywhere Agents 先给出了一条很严格的观察规则：看不到，不等于不存在 <a class="header-anchor" href="#_1-anywhere-agents-先给出了一条很严格的观察规则-看不到-不等于不存在" aria-label="Permalink to &quot;1. Anywhere Agents 先给出了一条很严格的观察规则：看不到，不等于不存在&quot;">​</a></h2><p>Yue Zhao 在 Anywhere Agents 的提交 <code>570c89f</code> 中处理了一批被中断后留下的 <code>prun-task-*</code> 工作单元。作者报告：有 <strong>27 个工作单元已经记录结果路径，但对应结果文件已经消失；同时仍保留 24.3 MiB 的尾部输出</strong>。这些数字来自该提交的工程现场报告，本文没有独立复现。</p><p>更值得注意的不是数量，而是它对“观察失败”的处理方式。<code>report-state</code> 没有把工作单元简化成“可恢复 / 已失败 / 可重派”，而是拆成两个正交字段：</p><ul><li><code>result_path_state</code>：记录的结果路径是否能被解析；</li><li><code>result</code>：目标文件当前到底是 <code>present / empty / missing / unknown</code>。</li></ul><p>只有明确收到 <code>FileNotFoundError</code>，工具才允许把结果写成 <code>missing</code>。权限拒绝、I/O 错误、非普通文件、入口过长或根目录不可读，都不会被偷换成“不存在”。提交里的原则可以直接翻成中文：</p><blockquote><p><strong>观察失败，不能自动变成执行结论。</strong></p></blockquote><p>这条规则对“取消 Agent”同样适用。根进程 PID 看不到，最多说明这个 PID 当前不可观察；只有拥有更强的进程约束证据，系统才有资格把结论扩大到整个执行树。</p><h2 id="_2-issue-29-更进一步-四轮更强的-已回收-都被反例推翻" tabindex="-1">2. Issue #29 更进一步：四轮更强的“已回收”都被反例推翻 <a class="header-anchor" href="#_2-issue-29-更进一步-四轮更强的-已回收-都被反例推翻" aria-label="Permalink to &quot;2. Issue #29 更进一步：四轮更强的“已回收”都被反例推翻&quot;">​</a></h2><p>Anywhere Agents 的开放 Issue #29 很有研究价值，因为它不是只提出“孤儿进程难处理”，而是记录了四轮逐步加强的 <code>reap-orphans</code> 方案，以及每一轮为什么仍然不足。</p><table tabindex="0"><thead><tr><th>轮次</th><th>当时想证明什么</th><th>被什么反例推翻</th></tr></thead><tbody><tr><td>第 1 轮</td><td>已发送信号，所以可以说 <code>REAPED</code></td><td><code>kill</code> 全部失败，仍然报告 <code>REAPED</code></td></tr><tr><td>第 2 轮</td><td>记录的根进程已消失</td><td>后代进程忽略 <code>TERM</code> 后继续存活</td></tr><tr><td>第 3 轮</td><td>进程组已经为空</td><td>后代进程用 <code>setsid</code> 离开原进程组</td></tr><tr><td>第 4 轮</td><td>多轮快照已经收敛到固定点</td><td>一个短寿命中间进程在两次枚举之间生成孙进程后退出，孙进程从未进入已观察集合</td></tr></tbody></table><p>第 4 轮尤其关键：它不需要 PID 复用、不需要查询失败，也不需要扫描超时。纯粹依靠时序，就可以出现：回收器认为已经收敛、打印 <code>REAPED</code>，但孙进程仍然活着。</p><p>因此，Issue 最后的结论不是“再多扫几遍”，而是把证明责任前移到<strong>派发时</strong>：如果工作进程在启动时没有被放进一个受内核约束的封闭集合，之后的回收器只能通过 PID、父子关系和进程组去推断成员，而这些关系都可以逃逸。</p><p>作者提出的方向是：Windows 使用 <strong>Job Object（作业对象）</strong>，POSIX 保证独立会话或使用 <code>setsid</code>；只有在进程启动时先建立内核级约束，后续回收器才有资格对整个执行树作更强的后置条件声明。该 Issue 甚至把 <code>REAPED</code> 保留给内核级进程约束，在这一前提真正实现之前不让它成为可达结果。</p><p>这不是 CodeFlowMu 的实现依据，也不证明我们的运行时存在同样缺陷。但它给出一个非常有用的审计原则：</p><blockquote><p><strong>停止范围越大，证明责任越不能只靠“我现在没看见它”。</strong></p></blockquote><h2 id="_3-一个-已停止-状态至少压着六种不同事实" tabindex="-1">3. 一个“已停止”状态至少压着六种不同事实 <a class="header-anchor" href="#_3-一个-已停止-状态至少压着六种不同事实" aria-label="Permalink to &quot;3. 一个“已停止”状态至少压着六种不同事实&quot;">​</a></h2><p>为了避免把动作和后置条件混在一起，可以把取消现场拆成下面几层：</p><table tabindex="0"><thead><tr><th>事实层</th><th>能证明什么</th><th>不能证明什么</th></tr></thead><tbody><tr><td>已请求取消</td><td>运行时确实发出了取消意图</td><td>操作系统已经停止任何进程</td></tr><tr><td>终止命令成功</td><td>终止工具返回了成功结果</td><td>所有后代进程都已退出</td></tr><tr><td>已观察到根进程退出</td><td>已知根进程或外层进程 PID 不再可观察</td><td>子进程、孙进程、句柄、端口都清理完毕</td></tr><tr><td>已观察到已知子进程退出</td><td>已知直接子进程已退出</td><td>没有逃逸的后代进程</td></tr><tr><td>已证明进程约束成立</td><td>执行单元属于可被整体约束的封闭集合</td><td>工作区一定没有异步尾部写入</td></tr><tr><td>已具备重新派工资格</td><td>调度规则允许新一轮执行</td><td>上一轮所有操作系统资源都已被证明消失</td></tr></tbody></table><p>这六层可以互相引用，但不能互相代签。</p><p>尤其要避免两种跳跃：</p><p><strong><code>taskkill</code> 返回 0 → 整棵执行树已经消失</strong></p><p>以及：</p><p><strong>PM 允许重试 → 上一轮执行一定已经完全结束</strong></p><p>前者把工具结果扩写成操作系统级进程约束事实；后者把治理许可扩写成进程事实。</p><h2 id="_4-我们自己的-windows-探针到底证明了什么" tabindex="-1">4. 我们自己的 Windows 探针到底证明了什么 <a class="header-anchor" href="#_4-我们自己的-windows-探针到底证明了什么" aria-label="Permalink to &quot;4. 我们自己的 Windows 探针到底证明了什么&quot;">​</a></h2><p>CodeFlowMu 是我们正在开发的本地多 Agent 运行时。第一方代码路径在 Windows 上使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>taskkill /PID &lt;pid&gt; /T /F</span></span></code></pre></div><p>来终止受管命令的外层进程，以及 Windows 对该 PID 可识别的进程树。</p><p>我们没有直接把这条命令写成“进程树已安全收拢”。相反，我们做了一个故意很窄的实验：在新的临时目录里启动一个外层进程，再由它启动一个长寿命直接子进程；确认两个 PID 都存在后，对外层进程执行同一条 <code>taskkill /T /F</code>，随后分别观察两个 PID。</p><p>那次受控 Windows 主机记录为：</p><ul><li><code>taskkill</code> 退出码 = <code>0</code>；</li><li>外层进程退出已观察 = <code>true</code>；</li><li>直接子进程退出已观察 = <code>true</code>；</li><li><code>kernel_containment_proven = false</code>。</li></ul><p>因此这次 <strong>PASS</strong> 只能支持一句很窄的话：</p><blockquote><p><strong>在这个 Windows 主机、这个“外层进程 + 直接子进程”的样本中，<code>/T</code> 没有只结束外层进程；两个已知 PID 都被观察到退出。</strong></p></blockquote><p>它不能支持：</p><blockquote><p>“任意深度的 Windows Agent 进程树都已被证明收拢。”</p></blockquote><p>目前公开证据包已经把这个实验合同物化成 Windows 专用探针，并公开了脱敏已记录结果和记录检查脚本。读者可以在自己的 Windows 机器上重新运行同一二层合同；非 Windows 主机则直接拒绝运行，不会返回假 PASS。</p><p>这比只给一行“1/1 PASS”更重要，因为<strong>可重跑不等于扩大结论</strong>。即使别的 Windows 主机再次 PASS，也仍然没有覆盖逃逸的后代进程、短寿命中间进程、跨权限、更深层级、容器或远程工作进程。</p><h2 id="_5-cancelled-更适合被理解成控制面结果-而不是执行树收拢证明" tabindex="-1">5. <code>cancelled</code> 更适合被理解成控制面结果，而不是执行树收拢证明 <a class="header-anchor" href="#_5-cancelled-更适合被理解成控制面结果-而不是执行树收拢证明" aria-label="Permalink to &quot;5. \`cancelled\` 更适合被理解成控制面结果，而不是执行树收拢证明&quot;">​</a></h2><p>这里还有一个值得我们自己继续收紧的语义问题。</p><p>当前第一方受管命令路径在终止工具成功后，可以把本次命令记录进入 <code>cancelled</code>。这个字段对控制面是有价值的：它说明<strong>这次取消操作已经按当前机制执行完</strong>。但如果界面或后续调度把 <code>cancelled</code> 直接解释成“所有后代进程都不存在”，语义就超出了当前证据。</p><p>更稳健的停止记录应该拆成独立字段或独立证据轴，例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cancel_request          sent</span></span>
<span class="line"><span>termination_command     exit_0</span></span>
<span class="line"><span>root_exit               observed</span></span>
<span class="line"><span>known_child_exit        observed</span></span>
<span class="line"><span>containment             unverified</span></span>
<span class="line"><span>workspace_quiescence    unverified</span></span>
<span class="line"><span>redispatch_eligibility  decided_by_existing_rule</span></span></code></pre></div><p>这些英文名称在这里保留，是因为它们代表建议的机器可读字段；对应中文含义分别是：取消请求、终止命令、根进程退出、已知子进程退出、执行树约束、工作区静止状态和重新派工资格。</p><p>这样，“未知”不会被强行塞进“失败”，也不会因为控制命令成功就被涂成全绿。</p><h2 id="_6-静默也不能被写成死亡" tabindex="-1">6. 静默也不能被写成死亡 <a class="header-anchor" href="#_6-静默也不能被写成死亡" aria-label="Permalink to &quot;6. 静默也不能被写成死亡&quot;">​</a></h2><p>停止证据还有另一面：不仅不能把“看不到”写成“已经死了”，也不能把“暂时没有输出”写成“已经失活”。</p><p>我们重跑过一个既有的受管命令测试样本：受管作业经历模拟两小时静默、101 次观察，以及索引丢失后的重启恢复，仍然保持为可诊断记录。这个定向测试是 <strong>1/1 PASS</strong>。</p><p>它回答的不是进程树约束，而是另一条语义边界：</p><blockquote><p><strong>静默 ≠ 死亡。</strong></p></blockquote><p>和前面的：</p><blockquote><p><strong>已请求取消 ≠ 整棵执行树已消失。</strong></p></blockquote><p>其实属于同一种纪律——运行时应记录它真正观察到的事实，而不是用缺少新信号来补一个更方便的结论。</p><h2 id="_7-真正危险的是取消和重派之间的空白区" tabindex="-1">7. 真正危险的是取消和重派之间的空白区 <a class="header-anchor" href="#_7-真正危险的是取消和重派之间的空白区" aria-label="Permalink to &quot;7. 真正危险的是取消和重派之间的空白区&quot;">​</a></h2><p>为什么要这么较真？因为最昂贵的事故往往不是第一次执行失败，而是<strong>第二次执行启动得太早</strong>。</p><p>旧外层进程已经退出，但某个后代进程仍在写文件；PM 根据业务规则批准重试；新的 Agent 又拿到同一个工作区。此时执行租约可以阻止同一调度路径上的两个正式执行轮次同时占有执行权，但租约本身不能杀掉一个已经逃逸到运行时观察范围之外的操作系统进程。</p><p>所以“能否重派”至少要明确区分两种判断：</p><ul><li><strong>治理与调度资格</strong>：这项任务是否允许产生新的执行轮次；</li><li><strong>执行环境安全证据</strong>：旧执行现场是否已经达到当前要求的收拢程度。</li></ul><p>前者是任务治理问题，后者是运行环境问题。一个正确的调度许可不能替操作系统签字。</p><h2 id="_8-下一批反例比再加一个绿色状态更有价值" tabindex="-1">8. 下一批反例比再加一个绿色状态更有价值 <a class="header-anchor" href="#_8-下一批反例比再加一个绿色状态更有价值" aria-label="Permalink to &quot;8. 下一批反例比再加一个绿色状态更有价值&quot;">​</a></h2><p>如果继续研究这条问题，我认为最值得补的不是一个更漂亮的“已停止”标记，而是更具攻击性的反例：</p><ul><li>外层进程退出，直接子进程继续运行；</li><li>子进程主动脱离原进程组或父子关系；</li><li>短寿命中间进程在两次观察之间生成孙进程；</li><li>旧结果文件在根进程退出后继续增长；</li><li>取消完成与重新派工同时竞争；</li><li>进程退出但端口、文件锁或外部辅助进程仍未释放。</li></ul><p>每个实验都应该输出同一套结构：</p><p><strong>发生了什么动作 → 观察到哪些对象 → 哪些后置条件已证明 → 哪些仍未知 → 因此允许什么下一步。</strong></p><p>这比把所有结果压成 <code>cancelled=true</code> 更适合长期运行的 Agent 运行时。</p><h2 id="结论-停止不是一个按钮结果-而是一份有范围的证明" tabindex="-1">结论：停止不是一个按钮结果，而是一份有范围的证明 <a class="header-anchor" href="#结论-停止不是一个按钮结果-而是一份有范围的证明" aria-label="Permalink to &quot;结论：停止不是一个按钮结果，而是一份有范围的证明&quot;">​</a></h2><p>Anywhere Agents 的 <code>report-state</code> 提醒我们：<strong>观察失败不能变成结果。</strong> Issue #29 又进一步说明：<strong>如果执行树从一开始就不是一个被内核约束的封闭集合，事后枚举很难证明它已经完全消失。</strong></p><p>我们的 Windows 二层探针则给出一个更小、更具体的事实：<code>taskkill /T /F</code> 在一个“外层进程 + 直接子进程”样本上确实观察到了两者退出。这个事实值得保留，但也必须停在这里。</p><blockquote><p><strong>取消请求是一项动作；停止是一组后置条件；执行树收拢是一项更强的证明。</strong></p></blockquote><p>可靠的 Agent 运行时不需要假装知道所有事。它只需要在重新派工之前，明确告诉下一位执行者：<strong>什么已经停下，什么只是没看见，什么仍然没有被证明。</strong></p><hr><h2 id="公开证据" tabindex="-1">公开证据 <a class="header-anchor" href="#公开证据" aria-label="Permalink to &quot;公开证据&quot;">​</a></h2><ul><li><a href="/joinwell52/zh/research/evidence/2026-08-27-runtime-semantics-evidence-pack"><strong>Runtime 语义三篇文章：公开证据包</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-tree-probe.mjs"><strong>R1 Windows <code>taskkill /T /F</code> 公开探针</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result.json"><strong>R1 脱敏已记录结果</strong></a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r1-windows-taskkill-recorded-result-check.mjs"><strong>R1 已记录结果检查脚本</strong></a></li></ul><h2 id="来源与证据边界" tabindex="-1">来源与证据边界 <a class="header-anchor" href="#来源与证据边界" aria-label="Permalink to &quot;来源与证据边界&quot;">​</a></h2><h3 id="anywhere-agents" tabindex="-1">Anywhere Agents <a class="header-anchor" href="#anywhere-agents" aria-label="Permalink to &quot;Anywhere Agents&quot;">​</a></h3><ul><li><a href="https://github.com/yzhao062/anywhere-agents/commit/570c89f4c4bfa03bc5cea0a43a7fcf9fef0261ab" target="_blank" rel="noreferrer"><strong>commit <code>570c89f</code></strong></a>：本文引用其 <code>report-state</code> 对结果路径观察与结果结论的拆分，以及作者报告的 27 个遗留工作单元、24.3 MiB 尾部输出。数字为作者工程现场报告，本文未独立复现。</li><li><a href="https://github.com/yzhao062/anywhere-agents/issues/29" target="_blank" rel="noreferrer"><strong>Issue #29</strong></a>：本文引用四轮孤儿进程回收方案被实机反例逐步推翻，以及将整棵执行树的证明前移到派发时内核级进程约束的设计讨论。该 Issue 仍为开放状态，不能视为已发布完成方案。</li></ul><p>Anywhere Agents 只作为公开研究与工程参照；本文不据此声称 CodeFlowMu 与其共享根因、实现或已达到同一进程约束设计。</p><h3 id="第一方证据" tabindex="-1">第一方证据 <a class="header-anchor" href="#第一方证据" aria-label="Permalink to &quot;第一方证据&quot;">​</a></h3><p>R1 只覆盖一台 Windows 主机上的一个“外层进程 + 直接子进程”样本。公开探针让相同二层合同可以被重跑，但并不把历史 PASS 升级成 Windows Job Object 或其他内核级进程约束证明。本文也不声称所有 Windows 进程树、独立运行时、网络文件系统、容器或远程工作进程已获得同样保证。</p>`,82))])}const m=a(i,[["render",l]]);export{k as __pageData,m as default};
